def check_2x2(N):
    # Use coloring C_i,j = i + j - 1. Colors range from 1 to 2N - 1.
    colors = {}
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            colors[(i, j)] = i + j - 1

    for i in range(1, N):
        for j in range(1, N):
            block_colors = [
                colors[(i, j)],
                colors[(i+1, j)],
                colors[(i, j+1)],
                colors[(i+1, j+1)]
            ]
            # Check if at least two squares have the same color (i.e., size of set is <= 3)
            if len(set(block_colors)) == 4:
                print(f"Violation found at ({i}, {j}). Colors: {block_colors}")
                return False
    return True

# Test for N=3, where K=5
print("Testing 3x3 grid:")
if check_2x2(3):
    print("Condition satisfied for 3x3 grid.")
else:
    print("Condition violated for 3x3 grid.")
